/* ---------------------------------------------------------------- renderer / scene */
const stage = document.getElementById('stage');
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.75));
renderer.setSize(innerWidth, innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
stage.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xc6d3de, 150, 700);
const camera = new THREE.PerspectiveCamera(38, innerWidth / innerHeight, 0.1, 2500);
camera.position.set(30, 8, 30);

const SUN_DIR = new THREE.Vector3(-0.5, 0.78, 0.52).normalize();
const sun = new THREE.DirectionalLight(0xfff0dc, 3.0);
sun.castShadow = true;
