/* ---------------------------------------------------------------- run state helpers */
let sim = null;
const layout = s => ({ Lt: s.trackLength, wallX: s.trackLength - clamp(s.trackLength * 0.2, 6, 20) });

function track(S, body, obj, extra) {
  const t = body.translation(), q = body.rotation();
  const rec = {
    body, obj, inst: null, idx: -1, alive: true, gravel: false, foot: [0.3, 0.3], hy: 0.2, op: 0.4, boff: null,
    p0: new THREE.Vector3(t.x, t.y, t.z), p1: new THREE.Vector3(t.x, t.y, t.z),
    q0: new THREE.Quaternion(q.x, q.y, q.z, q.w), q1: new THREE.Quaternion(q.x, q.y, q.z, q.w), ...extra
  };
  S.tracked.push(rec);
  return rec;
}

/* ---------------------------------------------------------------- physics world + ground */
function buildWorld(S) {
  const s = S.s, Lt = S.lay.Lt, xEnd = Lt + RUNOFF, x0 = -14;
  const world = new RAPIER.World(V3(0, -s.gravity, 0));
  world.timestep = DT;
  world.numSolverIterations = 8;
  S.world = world;
  S.eq = new RAPIER.EventQueue(true);
  const gb = world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
  const add = d => { const c = world.createCollider(d.setCollisionGroups(CG_GROUND), gb); S.cmap.set(c.handle, { ground: true }); };
  add(RAPIER.ColliderDesc.cuboid(500, 0.5, 300).setTranslation(Lt / 2, -0.5, 0).setFriction(s.groundFriction).setRestitution(0.05));
  for (const sz of [-1, 1]) add(RAPIER.ColliderDesc.cuboid((xEnd - x0) / 2, 0.45, 0.08).setTranslation((x0 + xEnd) / 2, 0.45, sz * 9.05).setFriction(0.35).setRestitution(0.2));
  add(RAPIER.ColliderDesc.cuboid(0.7, 0.55, 14.5).setTranslation(xEnd + 0.7, 0.55, 0).setFriction(0.8).setRestitution(0.3));
}

/* ---------------------------------------------------------------- brick wall */
function buildWall(S) {
  const s = S.s, w = s.brickW, h = s.brickH, d = s.brickD, gap = 0.006, gd = 0.004;
  const pitch = w + gap, total = s.cols * pitch - gap, halfW = (w - gap) / 2;
  const items = [];
  for (let k = 0; k < s.depth; k++) for (let r = 0; r < s.rows; r++) {
    const x = S.lay.wallX + d / 2 + k * (d + gd), y = h / 2 + r * h;
    if (((r + k) & 1) === 0) {
      for (let i = 0; i < s.cols; i++) items.push([x, y, -total / 2 + w / 2 + i * pitch, 0]);
    } else {
      items.push([x, y, -total / 2 + halfW / 2, 1]);
      for (let j = 0; j < s.cols - 1; j++) items.push([x, y, -total / 2 + pitch / 2 + j * pitch + w / 2, 0]);
      items.push([x, y, total / 2 - halfW / 2, 1]);
    }
  }
  S.wallInfo = { total, height: s.rows * h, thick: s.depth * (d + gd) };
  const nHalf = items.reduce((a, it) => a + it[3], 0), nFull = items.length - nHalf;
  const inset = Math.min(0.009, h * 0.08, d * 0.08, halfW * 0.08);
  const rad = Math.min(0.012, h * 0.12, d * 0.12, halfW * 0.12);
  const imF = new THREE.InstancedMesh(new RoundedBoxGeometry(d - inset, h - inset, w - inset, 2, rad), MAT.brick, Math.max(1, nFull));
  const imH = new THREE.InstancedMesh(new RoundedBoxGeometry(d - inset, h - inset, halfW - inset, 2, rad), MAT.brick, Math.max(1, nHalf));
  imF.count = nFull; imH.count = nHalf;
  for (const im of [imF, imH]) { im.castShadow = true; im.receiveShadow = true; im.frustumCulled = false; S.root.add(im); }
  const density = s.brickMass / (w * h * d);
  const thr = Math.max(250, s.brickMass * (s.gravity + 2) * s.rows * 2.5);
  const rng = mulberry32(4242), col = new THREE.Color(), m4 = new THREE.Matrix4();
  let iF = 0, iH = 0;
  for (const [x, y, z, half] of items) {
    const hz = half ? halfW / 2 : w / 2;
    const body = S.world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(x, y, z).setSleeping(true)
      .setCcdEnabled(true).setLinearDamping(0.04).setAngularDamping(0.1));
    const c = S.world.createCollider(RAPIER.ColliderDesc.cuboid(d / 2, h / 2, hz).setDensity(density)
      .setFriction(s.brickFriction).setRestitution(s.brickRestitution).setCollisionGroups(CG_BRICK)
      .setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS).setContactForceEventThreshold(thr), body);
