    inst.setMatrixAt(idx, m4.makeTranslation(x, y, z));
    const rec = track(S, body, null, { kind: 'brick', inst, idx, foot: [d / 2, hz], hy: h / 2, op: 0.38 });
    S.cmap.set(c.handle, { brick: rec, body });
