/* ---------------------------------------------------------------- car */
const WHEELS = ['wheelFR', 'wheelFL', 'wheelRR', 'wheelRL'];
function buildCar(S) {
  const s = S.s, world = S.world;
  const sL = s.carLength / 4.2, sH = s.carHeight / 1.45, sW = s.carWidth / 1.8;
  const r = 0.32 * Math.min(sH, sL), ww = 0.22 * sW, dy = 0.32 * sH - r;
  const X = v => v * sL, Y = v => v * sH - dy, Z = v => v * sW;
  const ox = START_FRONT_X - X(2.10);
  const k = Math.sqrt(s.carMass / 1250);
  const car = { parts: [], links: [], P: {}, r, ww };
  S.car = car;
  const P = car.P;
  const zz = (zs, a, b) => zs > 0 ? [a, b] : [-b, -a];
  const B = (x0, x1, y0, y1, z0, z1) => ({ c: [X((x0 + x1) / 2), Y((y0 + y1) / 2), Z((z0 + z1) / 2)], h: [(x1 - x0) * sL / 2, (y1 - y0) * sH / 2, (z1 - z0) * sW / 2] });
  const T = (xa, ya, xb, yb, t, hz, zc = 0) => {
    const ax = X(xa), ay = Y(ya), bx = X(xb), by = Y(yb);
    return { c: [(ax + bx) / 2, (ay + by) / 2, Z(zc)], h: [Math.hypot(bx - ax, by - ay) / 2, t / 2, Z(hz)], rz: Math.atan2(by - ay, bx - ax) };
  };
  const pt = (x, y, z) => [X(x), Y(y), Z(z)];

  class VB {
    constructor() { this.bin = new Bin(); }
    box(mat, x0, x1, y0, y1, z0, z1, rad = 0) {
      const sx = (x1 - x0) * sL, sy = (y1 - y0) * sH, sz = (z1 - z0) * sW, rr = Math.min(rad, Math.min(sx, sy, sz) * 0.45);
      const g = rr > 0.002 ? new RoundedBoxGeometry(sx, sy, sz, 2, rr) : new THREE.BoxGeometry(sx, sy, sz);
      this.bin.add(mat, g.translate(X((x0 + x1) / 2), Y((y0 + y1) / 2), Z((z0 + z1) / 2)));
      return this;
    }
    tilt(mat, xa, ya, xb, yb, t, z0, z1) {
      const ax = X(xa), ay = Y(ya), bx = X(xb), by = Y(yb);
      const g = new THREE.BoxGeometry(Math.hypot(bx - ax, by - ay), t, (z1 - z0) * sW);
      g.rotateZ(Math.atan2(by - ay, bx - ax)).translate((ax + bx) / 2, (ay + by) / 2, Z((z0 + z1) / 2));
      this.bin.add(mat, g); return this;
    }
    poly(mat, pts, z0, z1, bevel = 0.008) {
      const sh = new THREE.Shape();
      pts.forEach(([x, y], i) => i ? sh.lineTo(X(x), Y(y)) : sh.moveTo(X(x), Y(y)));
      const depth = (z1 - z0) * sW;
      const g = new THREE.ExtrudeGeometry(sh, { depth: Math.max(0.002, depth - 2 * bevel), bevelEnabled: bevel > 0, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 2, curveSegments: 8 });
      this.bin.add(mat, g.translate(0, 0, Z(z0) + bevel)); return this;
    }
    arch(mat, x0, x1, y0, y1, axle, z0, z1) {
      const ax = X(axle), ay = r, ar = r * 1.08 + 0.02 * sH;
      const X0 = Math.min(X(x0), ax - ar - 0.01), X1 = Math.max(X(x1), ax + ar + 0.01);
      const sh = new THREE.Shape();
      sh.moveTo(X0, Y(y0)); sh.lineTo(ax - ar, Y(y0)); sh.lineTo(ax - ar, ay);
      sh.absarc(ax, ay, ar, Math.PI, 0, true);
      sh.lineTo(ax + ar, Y(y0)); sh.lineTo(X1, Y(y0)); sh.lineTo(X1, Y(y1)); sh.lineTo(X0, Y(y1)); sh.lineTo(X0, Y(y0));
      const bevel = 0.01, depth = (z1 - z0) * sW;
      const g = new THREE.ExtrudeGeometry(sh, { depth: Math.max(0.002, depth - 2 * bevel), bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 2, curveSegments: 20 });
      this.bin.add(mat, g.translate(0, 0, Z(z0) + bevel)); return this;
    }
    geo(mat, g) { this.bin.add(mat, g); return this; }
    build() { return this.bin.build(new THREE.Group(), true, true); }
  }

  function wheelVis(cx, cz, side) {
    const vb = new VB(), ri = r * 0.64, tw = ww / 2;
    const place = g => g.rotateX(Math.PI / 2).translate(cx, r, cz);
    const prof = [[ri * 1.02, -tw * 0.9], [r * 0.9, -tw], [r * 0.975, -tw * 0.84], [r, -tw * 0.42], [r, tw * 0.42], [r * 0.975, tw * 0.84], [r * 0.9, tw], [ri * 1.02, tw * 0.9]]
      .map(([a, b]) => new THREE.Vector2(a, b));
    vb.geo(MAT.tire, place(new THREE.LatheGeometry(prof, 32)));
    vb.geo(MAT.rim, place(new THREE.CylinderGeometry(ri, ri, ww * 0.82, 28, 1, true)));
    vb.geo(MAT.chrome, place(new THREE.TorusGeometry(ri, 0.012, 6, 28).rotateX(Math.PI / 2).translate(0, side * tw * 0.8, 0)));
    vb.geo(MAT.trim, place(new THREE.CylinderGeometry(ri * 0.97, ri * 0.97, 0.01, 24).translate(0, side * tw * 0.05, 0)));
    vb.geo(MAT.engine, place(new THREE.CylinderGeometry(ri * 0.72, ri * 0.72, 0.025, 24).translate(0, -side * tw * 0.12, 0)));
    for (let i = 0; i < 5; i++) vb.geo(MAT.rim, place(new THREE.BoxGeometry(0.05 * Math.max(0.8, sW), 0.03, ri * 0.92).translate(0, side * tw * 0.55, ri * 0.46).rotateY(i * Math.PI * 0.4)));
    vb.geo(MAT.chrome, place(new THREE.CylinderGeometry(ri * 0.2, ri * 0.22, 0.05, 16).translate(0, side * tw * 0.58, 0)));
    return vb.build();
  }

  function addPart(name, kind, frac, boxes, vis, o = {}) {
    const mass = s.carMass * frac;
    let vol = 0, cx = 0, cy = 0, cz = 0;
    for (const b of boxes) {
      const v = b.cyl ? Math.PI * b.rad * b.rad * 2 * b.h[2] : 8 * b.h[0] * b.h[1] * b.h[2];
      vol += v; cx += b.c[0] * v; cy += b.c[1] * v; cz += b.c[2] * v;
    }
    cx /= vol; cy /= vol; cz /= vol;
    const body = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(ox + cx, cy, cz)
      .setCcdEnabled(true).setLinearDamping(0.01).setAngularDamping(o.ad ?? 0.04));
    const cg = kind === 'struct' ? CG_STRUCT : CG_PART, dens = mass / vol, cols = [];
    for (const b of boxes) {
      const d = b.cyl ? RAPIER.ColliderDesc.cylinder(b.h[2], b.rad).setRotation(QX90) : RAPIER.ColliderDesc.cuboid(b.h[0], b.h[1], b.h[2]);
      if (b.rz) d.setRotation(quatZ(b.rz));
      d.setTranslation(b.c[0] - cx, b.c[1] - cy, b.c[2] - cz).setDensity(dens).setFriction(o.fr ?? 0.5).setRestitution(o.rest ?? 0.12)
        .setCollisionGroups(cg).setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS).setContactForceEventThreshold(o.thr ?? 600);
      cols.push(world.createCollider(d, body));
    }
    const obj = new THREE.Group();
    vis.position.set(-cx, -cy, -cz); obj.add(vis); obj.position.set(ox + cx, cy, cz); S.root.add(obj);
    let x0 = 1e9, x1 = -1e9, z0 = 1e9, z1 = -1e9, y0 = 1e9;
    for (const b of boxes) {
      x0 = Math.min(x0, b.c[0] - b.h[0]); x1 = Math.max(x1, b.c[0] + b.h[0]);
      z0 = Math.min(z0, b.c[2] - b.h[2]); z1 = Math.max(z1, b.c[2] + b.h[2]); y0 = Math.min(y0, b.c[1] - b.h[1]);
    }
    const part = {
      name, kind, body, obj, vis, mass, c: [cx, cy, cz], cols, links: [], alive: true, attached: true,
      pv: { x: 0, y: 0, z: 0 }, fc: 0, fcPrev: 0, fcAvg: 0, acc: 0, accPrev: 0, accAvg: 0, glass: o.glass || null, metal: o.metal ?? true
    };
    part.rec = track(S, body, obj, {
      kind: 'part', part, foot: o.foot || [(x1 - x0) / 2, (z1 - z0) / 2], hy: Math.max(0.02, cy - y0), op: o.blob ?? 0.45,
      boff: o.blobAt ? [o.blobAt[0] - cx, o.blobAt[1] - cy, o.blobAt[2] - cz] : null
    });
    for (const c of cols) S.cmap.set(c.handle, { part, body });
    car.parts.push(part); P[name] = part;
    return part;
  }

  /* --- cabin (safety cell): floor tub, sills, dash, rear box, roof, pillars */
  const cab = new VB()
    .box(MAT.paint, -1.02, 0.07, 1.385, 1.46, -0.83, 0.83, 0.035)
    .box(MAT.paint, -1.995, -1.95, 0.50, 0.905, -0.865, 0.865, 0.012)
    .box(MAT.paint, -1.97, -1.45, 0.86, 0.905, -0.85, 0.85)
    .box(MAT.trim, 0.56, 0.70, 0.86, 0.93, -0.80, 0.80)
    .box(MAT.trim, -1.95, 0.64, 0.15, 0.20, -0.80, 0.80)
    .box(MAT.interior, -1.20, 0.60, 0.40, 0.45, -0.80, 0.80)
    .box(MAT.interior, 0.28, 0.62, 0.62, 0.93, -0.80, 0.80, 0.03)
    .box(MAT.interior, -1.08, -0.52, 0.45, 0.72, -0.64, 0.64, 0.05)
    .box(MAT.interior, -1.12, -0.98, 0.70, 1.16, -0.64, 0.64, 0.04)
    .box(MAT.interior, -1.97, -1.12, 0.62, 0.86, -0.80, 0.80);
  for (const zs of [1, -1]) {
    cab.arch(MAT.paint, -1.97, -0.88, 0.22, 0.92, -1.26, ...zz(zs, 0.855, 0.895))
      .poly(MAT.paint, [[-0.92, 0.92], [-0.80, 1.40], [-1.02, 1.40], [-1.50, 0.92]], ...zz(zs, 0.80, 0.86))
      .tilt(MAT.paint, 0.66, 0.92, 0.05, 1.40, 0.07, ...zz(zs, 0.74, 0.86))
      .box(MAT.trim, -0.16, -0.10, 0.92, 1.40, ...zz(zs, 0.80, 0.86))
      .box(MAT.trim, -0.92, 0.64, 0.155, 0.24, ...zz(zs, 0.83, 0.905), 0.02)
      .box(MAT.tail, -2.005, -1.985, 0.72, 0.86, ...zz(zs, 0.50, 0.84), 0.01)
      .box(MAT.interior, -0.40, 0.08, 0.45, 0.66, ...zz(zs, 0.14, 0.62), 0.05)
      .box(MAT.interior, -0.46, -0.32, 0.62, 1.22, ...zz(zs, 0.16, 0.60), 0.05);
  }
  cab.geo(MAT.trim, new THREE.TorusGeometry(0.17 * sW, 0.018, 8, 24).rotateY(Math.PI / 2).rotateZ(0.45).translate(X(0.18), Y(1.0), Z(-0.38)));
  addPart('cabin', 'struct', 0.508, [
    B(-1.95, 0.60, 0.18, 0.62, -0.62, 0.62), B(-0.90, 0.60, 0.18, 0.40, 0.64, 0.84), B(-0.90, 0.60, 0.18, 0.40, -0.84, -0.64),
    B(0.30, 0.58, 0.63, 0.90, -0.70, 0.70), B(-1.95, -1.10, 0.68, 0.90, -0.80, 0.80), B(-1.00, 0.05, 1.39, 1.45, -0.80, 0.80),
    T(0.66, 0.93, 0.05, 1.38, 0.05, 0.03, 0.79), T(0.66, 0.93, 0.05, 1.38, 0.05, 0.03, -0.79),
    B(-0.15, -0.11, 0.93, 1.39, 0.76, 0.82), B(-0.15, -0.11, 0.93, 1.39, -0.82, -0.76)
  ], cab.build(), { thr: s.carMass * 9.81 * 0.8, blob: 0.8, foot: [X(2.1), Z(0.95)], blobAt: [0, Y(0.3), 0] });

  /* --- front clip A (crush zone with engine) and nose clip B */
  const aV = new VB()
    .box(MAT.engine, 0.80, 1.28, 0.36, 0.76, -0.34, 0.34, 0.03)
    .box(MAT.trim, 0.88, 1.20, 0.76, 0.80, -0.26, 0.26, 0.01)
    .box(MAT.trim, 0.62, 0.66, 0.30, 0.86, -0.62, 0.62);
  for (const zs of [1, -1]) aV.box(MAT.trim, 0.64, 1.35, 0.26, 0.36, ...zz(zs, 0.45, 0.56)).box(MAT.trim, 1.05, 1.25, 0.50, 0.80, ...zz(zs, 0.48, 0.60)).box(MAT.paint, 0.64, 1.35, 0.40, 0.80, ...zz(zs, 0.58, 0.62));
  const aRear = X(0.64), aPivot = new THREE.Group(), aInner = aV.build(), aWrap = new THREE.Group();
  aPivot.position.set(aRear, 0, 0); aInner.position.set(-aRear, 0, 0); aPivot.add(aInner); aWrap.add(aPivot);
  const clipA = addPart('clipA', 'struct', 0.14, [B(0.64, 1.35, 0.25, 0.80, -0.60, 0.60)], aWrap, { thr: 1500 });
  clipA.crushPivot = aPivot; clipA.crushLen = X(1.36 - 0.64);

  const bV = new VB()
    .box(MAT.paint, 1.66, 1.97, 0.50, 0.83, -0.86, 0.86, 0.04)
    .box(MAT.trim, 1.955, 1.985, 0.54, 0.72, -0.40, 0.40, 0.01)
    .box(MAT.engine, 1.40, 1.62, 0.30, 0.76, -0.55, 0.55, 0.01);
  for (const zs of [1, -1]) bV.box(MAT.chrome, 1.955, 1.973, 0.625, 0.785, ...zz(zs, 0.445, 0.815), 0.01).box(MAT.head, 1.93, 1.98, 0.64, 0.77, ...zz(zs, 0.46, 0.80), 0.02).box(MAT.trim, 1.37, 1.95, 0.26, 0.36, ...zz(zs, 0.45, 0.56));
  addPart('clipB', 'struct', 0.06, [B(1.37, 1.95, 0.25, 0.80, -0.60, 0.60), B(1.66, 1.95, 0.50, 0.80, -0.86, 0.86)], bV.build(), { thr: 1500 });

  /* --- bumpers, hood halves, trunk lid, fenders */
  addPart('bumperF', 'part', 0.012, [B(1.97, 2.10, 0.16, 0.50, -0.88, 0.88)], new VB()
    .box(MAT.paint, 1.97, 2.10, 0.17, 0.50, -0.89, 0.89, 0.05).box(MAT.trim, 1.99, 2.115, 0.16, 0.23, -0.80, 0.80, 0.02)
    .box(MAT.trim, 2.095, 2.108, 0.26, 0.36, -0.50, 0.50, 0.005).box(MAT.plate, 2.10, 2.115, 0.37, 0.47, -0.26, 0.26, 0.005).build());
  addPart('bumperR', 'part', 0.012, [B(-2.10, -1.97, 0.18, 0.50, -0.88, 0.88)], new VB()
    .box(MAT.paint, -2.10, -1.97, 0.17, 0.50, -0.89, 0.89, 0.05).box(MAT.trim, -2.115, -1.99, 0.16, 0.23, -0.80, 0.80, 0.02)
    .box(MAT.plate, -2.115, -2.10, 0.30, 0.42, -0.26, 0.26, 0.005).box(MAT.tail, -2.108, -2.098, 0.40, 0.44, 0.58, 0.80).box(MAT.tail, -2.108, -2.098, 0.40, 0.44, -0.80, -0.58).build());
  addPart('hoodR', 'part', 0.011, [B(0.70, 1.30, 0.82, 0.86, -0.84, 0.84)], new VB().box(MAT.paint, 0.70, 1.31, 0.82, 0.875, -0.845, 0.845, 0.018).build());
  addPart('hoodF', 'part', 0.011, [B(1.32, 1.95, 0.82, 0.86, -0.84, 0.84)], new VB().box(MAT.paint, 1.31, 1.965, 0.82, 0.875, -0.845, 0.845, 0.018).build());
  addPart('trunk', 'part', 0.012, [B(-1.95, -1.47, 0.91, 0.95, -0.84, 0.84)], new VB()
    .box(MAT.paint, -1.965, -1.46, 0.905, 0.955, -0.85, 0.85, 0.018).box(MAT.trim, -1.975, -1.90, 0.955, 0.985, -0.78, 0.78, 0.01).build());
  for (const zs of [1, -1]) addPart(zs > 0 ? 'fenderR' : 'fenderL', 'part', 0.008, [B(0.70, 1.62, 0.67, 0.86, ...zz(zs, 0.86, 0.90))],
    new VB().arch(MAT.paint, 0.64, 1.95, 0.30, 0.865, 1.30, ...zz(zs, 0.858, 0.90)).build());

  /* --- doors with their side glass */
  for (const zs of [1, -1]) for (const [nm, x0, x1] of [['F', -0.12, 0.62], ['R', -0.90, -0.14]]) {
    const id = nm + (zs > 0 ? 'R' : 'L');
    const v = new VB().box(MAT.paint, x0, x1, 0.20, 0.925, ...zz(zs, 0.852, 0.90), 0.02)
      .box(MAT.chrome, x1 - 0.26, x1 - 0.12, 0.76, 0.79, ...zz(zs, 0.899, 0.914), 0.006)
      .box(MAT.trim, x0 + 0.01, x1 - 0.01, 0.905, 0.935, ...zz(zs, 0.83, 0.862), 0.004);
    if (nm === 'F') v.box(MAT.paint, 0.44, 0.60, 0.95, 1.05, ...zz(zs, 0.88, 1.02), 0.03).box(MAT.chrome, 0.432, 0.442, 0.96, 1.04, ...zz(zs, 0.89, 1.01), 0.003);
    addPart('door' + id, 'part', 0.02, [B(x0, x1, 0.20, 0.92, ...zz(zs, 0.85, 0.90))], v.build());
    const gpts = nm === 'F' ? [[-0.12, 0.95], [0.60, 0.95], [0.07, 1.35], [-0.12, 1.35]] : [[-0.14, 0.95], [-0.14, 1.35], [-0.78, 1.35], [-0.95, 0.95]];
    const gb = nm === 'F' ? B(-0.10, 0.26, 0.96, 1.20, ...zz(zs, 0.835, 0.855)) : B(-0.79, -0.16, 0.96, 1.30, ...zz(zs, 0.835, 0.855));
    addPart('glass' + id, 'part', 0.004, [gb], new VB().poly(MAT.glass, gpts, ...zz(zs, 0.839, 0.851), 0).build(),
      { metal: false, blob: 0.1, glass: { kind: 'side', poly: gpts.map(([x, y]) => [X(x), Y(y)]), zc: Z(0.845) * zs, nx: 4, ny: 3 } });
  }

  /* --- windshield + rear window */
  const wsB = T(0.66, 0.93, 0.05, 1.37, 0.012, 0.74);
  addPart('windshield', 'part', 0.012, [wsB], new VB().tilt(MAT.glass, 0.66, 0.93, 0.05, 1.37, 0.012, -0.76, 0.76).build(),
    { metal: false, blob: 0.1, glass: { kind: 'tilt', rz: wsB.rz, hu: wsB.h[0], hw: Z(0.74), nx: 5, ny: 4 } });
  const rgB = T(-1.00, 1.37, -1.45, 0.96, 0.012, 0.74);
  addPart('rearGlass', 'part', 0.010, [rgB], new VB().tilt(MAT.glass, -1.00, 1.37, -1.45, 0.96, 0.012, -0.76, 0.76).build(),
    { metal: false, blob: 0.1, glass: { kind: 'tilt', rz: rgB.rz, hu: rgB.h[0], hw: Z(0.74), nx: 4, ny: 3 } });

  /* --- wheels */
  for (const [nm, axle, zs] of [['wheelFR', 1.30, 1], ['wheelFL', 1.30, -1], ['wheelRR', -1.26, 1], ['wheelRL', -1.26, -1]]) {
    const cx = X(axle), cz = Z(0.76) * zs;
    addPart(nm, 'part', 0.025, [{ cyl: true, rad: r, c: [cx, r, cz], h: [r, r, ww / 2] }], wheelVis(cx, cz, zs),
      { fr: 1.05, rest: 0.1, thr: s.carMass * 9.81 * 0.6, ad: 0.02, blob: 0.62, metal: false });
  }
  car.frontOff = X(2.10) - P.bumperF.c[0];

  /* --- breakable joint graph */
  function link(parent, child, at, stages, o = {}) {
    const a1 = [at[0] - parent.c[0], at[1] - parent.c[1], at[2] - parent.c[2]];
    const a2 = [at[0] - child.c[0], at[1] - child.c[1], at[2] - child.c[2]];
    const st = stages[0];
    const jd = st.type === 'revolute'
      ? RAPIER.JointData.revolute(V3(...a1), V3(...a2), V3(...st.axis))
      : RAPIER.JointData.fixed(V3(...a1), QI, V3(...a2), QI);
    const joint = world.createImpulseJoint(jd, parent.body, child.body, true);
    const L = { parent, child, a1, a2, stages, stage: 0, joint, alive: true, fc: 0, crush: 0, drift: 0, shatter: !!o.shatter, noContacts: !!o.noContacts, subtree: null, weakBy: null, onCrush: null };
    if (L.noContacts) joint.setContactsEnabled(false);
    child.links.push(L); car.links.push(L);
    return L;
  }
  const LA = link(P.cabin, P.clipA, pt(0.63, 0.50, 0), [
    { type: 'fixed', sC: 55000 * k, drift: 0.05 },
    { type: 'crush', travel: X(0.26), damp: 6000 * k, sC: 260000 * k, drift: 0.2 }]);
  const LB = link(P.clipA, P.clipB, pt(1.36, 0.50, 0), [
    { type: 'fixed', sC: 32000 * k, drift: 0.05 },
    { type: 'crush', travel: X(0.36), damp: 2600 * k, sC: 150000 * k, drift: 0.2 }]);
  car.LA = LA; car.LB = LB;
  for (const [nm, par, axle, zs] of [['wheelFR', P.clipA, 1.30, 1], ['wheelFL', P.clipA, 1.30, -1], ['wheelRR', P.cabin, -1.26, 1], ['wheelRL', P.cabin, -1.26, -1]]) {
    const L = link(par, P[nm], [X(axle), r, Z(0.76) * zs], [{ type: 'revolute', axis: [0, 0, 1], sC: (par === P.clipA ? 12000 : 15000) * k, drift: 0.07 }]);
    if (par === P.clipA) L.weakBy = [LA, LB];
  }
  link(P.clipB, P.bumperF, pt(1.97, 0.33, 0), [{ type: 'fixed', sC: 15000 * k, aI: 500, drift: 0.05 }]);
  link(P.cabin, P.bumperR, pt(-1.97, 0.34, 0), [{ type: 'fixed', sC: 15000 * k, aI: 500, drift: 0.05 }]);
  for (const zs of [1, -1]) link(P.clipA, P[zs > 0 ? 'fenderR' : 'fenderL'], pt(1.10, 0.76, 0.88 * zs), [{ type: 'fixed', sC: 4500 * k, aI: 600, drift: 0.04 }]).weakBy = [LA, LB];
  const LhR = link(P.cabin, P.hoodR, pt(0.70, 0.845, 0), [
    { type: 'fixed', sC: 9000 * k, aI: 450, drift: 0.04 },
    { type: 'hinge', axis: [0, 0, 1], at: pt(0.70, 0.86, 0), sC: 22000 * k, aI: 1400, drift: 0.09 }]);
  const LhF = link(P.clipB, P.hoodF, pt(1.95, 0.845, 0), [
    { type: 'fixed', sC: 8000 * k, aI: 450, drift: 0.04 },
    { type: 'hinge', axis: [0, 0, 1], at: pt(1.95, 0.86, 0), sC: 20000 * k, aI: 1400, drift: 0.09 }]);
  const LhM = link(P.hoodR, P.hoodF, pt(1.31, 0.845, 0), [
    { type: 'fixed', sC: 7000 * k, aI: 600, drift: 0.04 },
    { type: 'hinge', axis: [0, 0, 1], at: pt(1.31, 0.875, 0), sC: 24000 * k, aI: 1600, drift: 0.09, nudge: 1.3 }], { noContacts: true });
  LB.onCrush = [LhF, LhM]; LA.onCrush = [LhR, LhM];
  LB.subtree = [P.clipB, P.bumperF, P.hoodF];
  LA.subtree = [P.clipA, P.clipB, P.bumperF, P.hoodF, P.fenderR, P.fenderL, P.wheelFR, P.wheelFL];
  for (const zs of [1, -1]) for (const [nm, x0, x1] of [['F', -0.12, 0.62], ['R', -0.90, -0.14]]) {
    const id = nm + (zs > 0 ? 'R' : 'L');
    link(P.cabin, P['door' + id], pt(x1, 0.56, 0.90 * zs), [
      { type: 'fixed', sC: 3500 * k, aI: 320, drift: 0.035 },
      { type: 'hinge', axis: [0, 1, 0], at: pt(x1, 0.56, 0.90 * zs), sC: 9000 * k, aI: 800, drift: 0.09, kick: { at: pt(x0, 0.56, 0.875 * zs), dir: [0, 0, zs], dv: 0.9 } }]);
    link(P['door' + id], P['glass' + id], P['glass' + id].c.slice(), [{ type: 'fixed', sC: 1100, aI: 380, drift: 0.03 }], { shatter: true });
  }
  link(P.cabin, P.windshield, P.windshield.c.slice(), [{ type: 'fixed', sC: 2000, aI: 420, drift: 0.03, dep: { link: LA, ratio: 0.35 } }], { shatter: true });
  link(P.cabin, P.rearGlass, P.rearGlass.c.slice(), [{ type: 'fixed', sC: 1400, aI: 420, drift: 0.03 }], { shatter: true });
  link(P.cabin, P.trunk, pt(-1.47, 0.93, 0), [
    { type: 'fixed', sC: 4000 * k, aI: 300, drift: 0.04 },
    { type: 'hinge', axis: [0, 0, 1], at: pt(-1.47, 0.955, 0), sC: 10000 * k, aI: 800, drift: 0.09 }]);
}

//@@NEXT@@

/* ---------------------------------------------------------------- car */
const WHEELS = ['wheelFR', 'wheelFL', 'wheelRR', 'wheelRL'];
function buildCar(S) {
  const s = S.s, world = S.world;
  const sL = s.carLength / 4.2, sH = s.carHeight / 1.45, sW = s.carWidth / 1.8;
  const r = 0.32 * Math.min(sH, sL), ww = 0.22 * sW, dy = 0.32 * sH - r;
  const X = v => v * sL, Y = v => v * sH - dy, Z = v => v * sW;
  const ox = START_FRONT_X - X(2.10);
  const k = Math.sqrt(s.carMass / 1250);
  const car = { parts: [], links: [], P: {}, r, ww };
  S.car = car;
  const P = car.P;
  const zz = (zs, a, b) => zs > 0 ? [a, b] : [-b, -a];
  const B = (x0, x1, y0, y1, z0, z1) => ({ c: [X((x0 + x1) / 2), Y((y0 + y1) / 2), Z((z0 + z1) / 2)], h: [(x1 - x0) * sL / 2, (y1 - y0) * sH / 2, (z1 - z0) * sW / 2] });
  const T = (xa, ya, xb, yb, t, hz, zc = 0) => {
    const ax = X(xa), ay = Y(ya), bx = X(xb), by = Y(yb);
    return { c: [(ax + bx) / 2, (ay + by) / 2, Z(zc)], h: [Math.hypot(bx - ax, by - ay) / 2, t / 2, Z(hz)], rz: Math.atan2(by - ay, bx - ax) };
  };
  const pt = (x, y, z) => [X(x), Y(y), Z(z)];

  class VB {
    constructor() { this.bin = new Bin(); }
    box(mat, x0, x1, y0, y1, z0, z1, rad = 0) {
      const sx = (x1 - x0) * sL, sy = (y1 - y0) * sH, sz = (z1 - z0) * sW, rr = Math.min(rad, Math.min(sx, sy, sz) * 0.45);
      const g = rr > 0.002 ? new RoundedBoxGeometry(sx, sy, sz, 2, rr) : new THREE.BoxGeometry(sx, sy, sz);
      this.bin.add(mat, g.translate(X((x0 + x1) / 2), Y((y0 + y1) / 2), Z((z0 + z1) / 2)));
      return this;
    }
    tilt(mat, xa, ya, xb, yb, t, z0, z1) {
      const ax = X(xa), ay = Y(ya), bx = X(xb), by = Y(yb);
      const g = new THREE.BoxGeometry(Math.hypot(bx - ax, by - ay), t, (z1 - z0) * sW);
      g.rotateZ(Math.atan2(by - ay, bx - ax)).translate((ax + bx) / 2, (ay + by) / 2, Z((z0 + z1) / 2));
      this.bin.add(mat, g); return this;
    }
    poly(mat, pts, z0, z1, bevel = 0.008) {
      const sh = new THREE.Shape();
      pts.forEach(([x, y], i) => i ? sh.lineTo(X(x), Y(y)) : sh.moveTo(X(x), Y(y)));
      const depth = (z1 - z0) * sW;
      const g = new THREE.ExtrudeGeometry(sh, { depth: Math.max(0.002, depth - 2 * bevel), bevelEnabled: bevel > 0, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 2, curveSegments: 8 });
      this.bin.add(mat, g.translate(0, 0, Z(z0) + bevel)); return this;
    }
    arch(mat, x0, x1, y0, y1, axle, z0, z1) {
      const ax = X(axle), ay = r, ar = r * 1.08 + 0.02 * sH;
      const X0 = Math.min(X(x0), ax - ar - 0.01), X1 = Math.max(X(x1), ax + ar + 0.01);
      const sh = new THREE.Shape();
      sh.moveTo(X0, Y(y0)); sh.lineTo(ax - ar, Y(y0)); sh.lineTo(ax - ar, ay);
      sh.absarc(ax, ay, ar, Math.PI, 0, true);
      sh.lineTo(ax + ar, Y(y0)); sh.lineTo(X1, Y(y0)); sh.lineTo(X1, Y(y1)); sh.lineTo(X0, Y(y1)); sh.lineTo(X0, Y(y0));
      const bevel = 0.01, depth = (z1 - z0) * sW;
      const g = new THREE.ExtrudeGeometry(sh, { depth: Math.max(0.002, depth - 2 * bevel), bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 2, curveSegments: 20 });
      this.bin.add(mat, g.translate(0, 0, Z(z0) + bevel)); return this;
    }
    geo(mat, g) { this.bin.add(mat, g); return this; }
    build() { return this.bin.build(new THREE.Group(), true, true); }
  }

  function wheelVis(cx, cz, side) {
    const vb = new VB(), ri = r * 0.64, tw = ww / 2;
    const place = g => g.rotateX(Math.PI / 2).translate(cx, r, cz);
    const prof = [[ri * 1.02, -tw * 0.9], [r * 0.9, -tw], [r * 0.975, -tw * 0.84], [r, -tw * 0.42], [r, tw * 0.42], [r * 0.975, tw * 0.84], [r * 0.9, tw], [ri * 1.02, tw * 0.9]]
      .map(([a, b]) => new THREE.Vector2(a, b));
    vb.geo(MAT.tire, place(new THREE.LatheGeometry(prof, 32)));
    vb.geo(MAT.rim, place(new THREE.CylinderGeometry(ri, ri, ww * 0.82, 28, 1, true)));
    vb.geo(MAT.chrome, place(new THREE.TorusGeometry(ri, 0.012, 6, 28).rotateX(Math.PI / 2).translate(0, side * tw * 0.8, 0)));
    vb.geo(MAT.trim, place(new THREE.CylinderGeometry(ri * 0.97, ri * 0.97, 0.01, 24).translate(0, side * tw * 0.05, 0)));
    vb.geo(MAT.engine, place(new THREE.CylinderGeometry(ri * 0.72, ri * 0.72, 0.025, 24).translate(0, -side * tw * 0.12, 0)));
    for (let i = 0; i < 5; i++) vb.geo(MAT.rim, place(new THREE.BoxGeometry(0.05 * Math.max(0.8, sW), 0.03, ri * 0.92).translate(0, side * tw * 0.55, ri * 0.46).rotateY(i * Math.PI * 0.4)));
    vb.geo(MAT.chrome, place(new THREE.CylinderGeometry(ri * 0.2, ri * 0.22, 0.05, 16).translate(0, side * tw * 0.58, 0)));
    return vb.build();
  }

  function addPart(name, kind, frac, boxes, vis, o = {}) {
    const mass = s.carMass * frac;
    let vol = 0, cx = 0, cy = 0, cz = 0;
    for (const b of boxes) {
      const v = b.cyl ? Math.PI * b.rad * b.rad * 2 * b.h[2] : 8 * b.h[0] * b.h[1] * b.h[2];
      vol += v; cx += b.c[0] * v; cy += b.c[1] * v; cz += b.c[2] * v;
    }
    cx /= vol; cy /= vol; cz /= vol;
    const body = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(ox + cx, cy, cz)
      .setCcdEnabled(true).setLinearDamping(0.01).setAngularDamping(o.ad ?? 0.04));
    const cg = kind === 'struct' ? CG_STRUCT : CG_PART, dens = mass / vol, cols = [];
    for (const b of boxes) {
      const d = b.cyl ? RAPIER.ColliderDesc.cylinder(b.h[2], b.rad).setRotation(QX90) : RAPIER.ColliderDesc.cuboid(b.h[0], b.h[1], b.h[2]);
      if (b.rz) d.setRotation(quatZ(b.rz));
      d.setTranslation(b.c[0] - cx, b.c[1] - cy, b.c[2] - cz).setDensity(dens).setFriction(o.fr ?? 0.5).setRestitution(o.rest ?? 0.12)
        .setCollisionGroups(cg).setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS).setContactForceEventThreshold(o.thr ?? 600);
      cols.push(world.createCollider(d, body));
    }
    const obj = new THREE.Group();
    vis.position.set(-cx, -cy, -cz); obj.add(vis); obj.position.set(ox + cx, cy, cz); S.root.add(obj);
    let x0 = 1e9, x1 = -1e9, z0 = 1e9, z1 = -1e9, y0 = 1e9;
    for (const b of boxes) {
      x0 = Math.min(x0, b.c[0] - b.h[0]); x1 = Math.max(x1, b.c[0] + b.h[0]);
      z0 = Math.min(z0, b.c[2] - b.h[2]); z1 = Math.max(z1, b.c[2] + b.h[2]); y0 = Math.min(y0, b.c[1] - b.h[1]);
    }
    const part = {
      name, kind, body, obj, vis, mass, c: [cx, cy, cz], cols, links: [], alive: true, attached: true,
      pv: { x: 0, y: 0, z: 0 }, fc: 0, fcPrev: 0, fcAvg: 0, acc: 0, accPrev: 0, accAvg: 0, glass: o.glass || null, metal: o.metal ?? true
    };
    part.rec = track(S, body, obj, {
      kind: 'part', part, foot: o.foot || [(x1 - x0) / 2, (z1 - z0) / 2], hy: Math.max(0.02, cy - y0), op: o.blob ?? 0.45,
      boff: o.blobAt ? [o.blobAt[0] - cx, o.blobAt[1] - cy, o.blobAt[2] - cz] : null
    });
    for (const c of cols) S.cmap.set(c.handle, { part, body });
    car.parts.push(part); P[name] = part;
    return part;
  }

  /* --- cabin (safety cell): floor tub, sills, dash, rear box, roof, pillars */
  const cab = new VB()
    .box(MAT.paint, -1.02, 0.07, 1.385, 1.46, -0.83, 0.83, 0.035)
    .box(MAT.paint, -1.995, -1.95, 0.50, 0.905, -0.865, 0.865, 0.012)
    .box(MAT.paint, -1.97, -1.45, 0.86, 0.905, -0.85, 0.85)
    .box(MAT.trim, 0.56, 0.70, 0.86, 0.93, -0.80, 0.80)
    .box(MAT.trim, -1.95, 0.64, 0.15, 0.20, -0.80, 0.80)
    .box(MAT.interior, -1.20, 0.60, 0.40, 0.45, -0.80, 0.80)
    .box(MAT.interior, 0.28, 0.62, 0.62, 0.93, -0.80, 0.80, 0.03)
    .box(MAT.interior, -1.08, -0.52, 0.45, 0.72, -0.64, 0.64, 0.05)
    .box(MAT.interior, -1.12, -0.98, 0.70, 1.16, -0.64, 0.64, 0.04)
    .box(MAT.interior, -1.97, -1.12, 0.62, 0.86, -0.80, 0.80);
  for (const zs of [1, -1]) {
    cab.arch(MAT.paint, -1.97, -0.88, 0.22, 0.92, -1.26, ...zz(zs, 0.855, 0.895))
      .poly(MAT.paint, [[-0.92, 0.92], [-0.80, 1.40], [-1.02, 1.40], [-1.50, 0.92]], ...zz(zs, 0.80, 0.86))
      .tilt(MAT.paint, 0.66, 0.92, 0.05, 1.40, 0.07, ...zz(zs, 0.74, 0.86))
      .box(MAT.trim, -0.16, -0.10, 0.92, 1.40, ...zz(zs, 0.80, 0.86))
      .box(MAT.trim, -0.92, 0.64, 0.155, 0.24, ...zz(zs, 0.83, 0.905), 0.02)
      .box(MAT.tail, -2.005, -1.985, 0.72, 0.86, ...zz(zs, 0.50, 0.84), 0.01)
      .box(MAT.interior, -0.40, 0.08, 0.45, 0.66, ...zz(zs, 0.14, 0.62), 0.05)
      .box(MAT.interior, -0.46, -0.32, 0.62, 1.22, ...zz(zs, 0.16, 0.60), 0.05);
  }
  cab.geo(MAT.trim, new THREE.TorusGeometry(0.17 * sW, 0.018, 8, 24).rotateY(Math.PI / 2).rotateZ(0.45).translate(X(0.18), Y(1.0), Z(-0.38)));
  addPart('cabin', 'struct', 0.508, [
    B(-1.95, 0.60, 0.18, 0.62, -0.62, 0.62), B(-0.90, 0.60, 0.18, 0.40, 0.64, 0.84), B(-0.90, 0.60, 0.18, 0.40, -0.84, -0.64),
    B(0.30, 0.58, 0.63, 0.90, -0.70, 0.70), B(-1.95, -1.10, 0.68, 0.90, -0.80, 0.80), B(-1.00, 0.05, 1.39, 1.45, -0.80, 0.80),
    T(0.66, 0.93, 0.05, 1.38, 0.05, 0.03, 0.79), T(0.66, 0.93, 0.05, 1.38, 0.05, 0.03, -0.79),
    B(-0.15, -0.11, 0.93, 1.39, 0.76, 0.82), B(-0.15, -0.11, 0.93, 1.39, -0.82, -0.76)
  ], cab.build(), { thr: s.carMass * 9.81 * 0.8, blob: 0.8, foot: [X(2.1), Z(0.95)], blobAt: [0, Y(0.3), 0] });

  /* --- front clip A (crush zone with engine) and nose clip B */
