/* ---------------------------------------------------------------- glass shard shapes (shared, visual only) */
const SHARD_GEOS = (() => {
  const rng = mulberry32(99), out = [];
  for (let i = 0; i < 8; i++) {
    const sh = new THREE.Shape(), j = () => rng() * 0.35;
    const pts = i % 3 === 0
      ? [[-0.5, -0.5 + j()], [0.5, -0.5], [-0.2 + j(), 0.5]]
      : [[-0.5 + j(), -0.5], [0.5, -0.5 + j()], [0.5 - j(), 0.5], [-0.5, 0.5 - j()]];
    pts.forEach(([x, y], n) => n ? sh.lineTo(x, y) : sh.moveTo(x, y));
    const g = new THREE.ExtrudeGeometry(sh, { depth: 1, bevelEnabled: false });
    g.translate(0, 0, -0.5).rotateX(Math.PI / 2);
    g.userData.shared = true;
    out.push(g);
  }
  return out;
})();

/* ---------------------------------------------------------------- run lifecycle */
function disposeRun() {
  if (!sim) return;
  sim.world.free();
  sim.eq.free();
  sim.root.traverse(o => {
    if ((o.isMesh || o.isInstancedMesh) && !o.geometry.userData.shared) o.geometry.dispose();
    if (o.isInstancedMesh) o.dispose();
  });
  scene.remove(sim.root);
  sim = null;
}

function restart(s) {
  disposeRun();
  settings = { ...s };
  const lay = layout(settings);
  if (envKey !== lay.Lt) buildEnvironment(lay.Lt);
  const S = {
    s: settings, lay, t: 0, acc: 0, steps: 0, phase: 0, impactT: null, impactV: null, braked: false, shake: 0, calm: 0,
    root: new THREE.Group(), cmap: new Map(), tracked: [], bricks: [], fxq: [], shardSeed: 1, launchT: 0.35
  };
  sim = S;
  scene.add(S.root);
  buildWorld(S);
  buildWall(S);
  buildCar(S);
  const V = settings.speed, dist = Math.max(0.5, lay.wallX - START_FRONT_X - 1.5);
  let a = V * V / (2 * dist), v0 = 0;
  if (a > 12) { a = 12; v0 = Math.sqrt(Math.max(0, V * V - 2 * a * dist)); }
  S.accel = a;
  if (v0 > 0) {
    S.launchT = 0;
    for (const p of S.car.parts) {
      p.body.setLinvel(V3(v0, 0, 0), true);
      p.pv = { x: v0, y: 0, z: 0 };
      if (p.name.startsWith('wheel')) p.body.setAngvel(V3(0, 0, -v0 / S.car.r), true);
    }
  }
  S.brickDustF = settings.brickMass * Math.max(1, settings.gravity) * 25 + 400;
  makeBlobs(S);
  makeSkids(S);
  FX.dust.reset(); FX.spark.reset();
  camState.snap = true;
}

/* ---------------------------------------------------------------- simulation step */
function stepSim(S) {
  if (S.phase < 2) drive(S);
  if ((S.steps & 3) === 0) gravelCheck(S);
  S.world.step(S.eq);
  S.t += DT; S.steps++;
  S.eq.drainContactForceEvents(ev => onForce(S, ev));
  updateParts(S);
  updateLinks(S);
  postStep(S);
}

function drive(S) {
  if (S.t < S.launchT) return;
  if (S.phase === 0) S.phase = 1;
  const car = S.car, V = S.s.speed, v = car.P.cabin.body.linvel().x;
  const dv = v < V ? Math.min(S.accel * DT, V - v) : (V - v) * 0.5;
  if (dv !== 0) for (const p of car.parts) if (p.alive && p.attached) p.body.applyImpulse(V3(p.mass * dv, 0, 0), true);
  if (car.P.bumperF.body.translation().x + car.frontOff >= S.lay.wallX - 0.005) markImpact(S);
}

function markImpact(S) {
  if (S.phase >= 2) return;
  S.phase = 2; S.impactT = S.t;
  S.impactV = S.car.P.cabin.body.linvel().x;
  S.shake = 1;
  S.fxq.push({ k: 'impact', p: [S.lay.wallX, 0.7, 0] });
}

function gravelCheck(S) {
  const Lt = S.lay.Lt;
  for (const r of S.tracked) {
    if (!r.alive || r.gravel) continue;
    const t = r.body.translation();
    if (t.x > Lt && Math.abs(t.z) < 14 && t.y < 1.2) {
      r.gravel = true;
      r.body.setLinearDamping(1.6);
      const braking = r.part && r.part.attached && r.part.name.startsWith('wheel') && S.braked;
      r.body.setAngularDamping(braking ? 28 : 1.2);
    }
  }
}

function onForce(S, ev) {
  const A = S.cmap.get(ev.collider1()), B = S.cmap.get(ev.collider2());
  if (!A || !B) return;
  const f = ev.totalForceMagnitude();
  if (A.part) A.part.fc += f;
  if (B.part) B.part.fc += f;
  const carBrick = (A.part && B.brick) || (B.part && A.brick);
  if (carBrick && S.phase < 2) markImpact(S);
  if (S.fxq.length > 60 || (A.brick && B.brick)) return;
  if (carBrick) {
    if (f > 4000) {
      const p1 = A.body.translation(), p2 = B.body.translation();
      S.fxq.push({ k: 'hit', p: [(p1.x + p2.x) / 2, (p1.y + p2.y) / 2, (p1.z + p2.z) / 2], f });
    }
  } else if ((A.brick && B.ground) || (A.ground && B.brick)) {
    if (f > S.brickDustF) { const p = (A.brick ? A : B).body.translation(); S.fxq.push({ k: 'dust', p: [p.x, 0.06, p.z], f }); }
  } else if ((A.part && B.ground) || (A.ground && B.part)) {
    const e = A.part ? A : B;
    if (e.part.metal && f > 1500) {
      const v = e.body.linvel(), sp = Math.hypot(v.x, v.z);
      if (sp > 3) { const p = e.body.translation(); S.fxq.push({ k: 'scrape', p: [p.x, 0.03, p.z], v: [v.x, v.z], f }); }
    }
  }
}

function updateParts(S) {
  const g = S.s.gravity;
  for (const p of S.car.parts) {
    if (!p.alive) continue;
    const v = p.body.linvel();
    const ax = (v.x - p.pv.x) / DT, ay = (v.y - p.pv.y) / DT + g, az = (v.z - p.pv.z) / DT;
    p.pv = v;
    p.acc = Math.hypot(ax, ay, az);
    p.fcAvg = 0.5 * (p.fc + p.fcPrev);
    p.accAvg = 0.5 * (p.acc + p.accPrev);
    p.fcPrev = p.fc; p.accPrev = p.acc; p.fc = 0;
  }
}

function crushRatio(L) {
  if (!L.alive) return 1;
  const st = L.stages[L.stage];
  return st.type === 'crush' ? clamp(L.crush / st.travel, 0, 1) : 0;
}

function updateLinks(S) {
  for (const L of S.car.links) {
    if (!L.alive) continue;
    const st = L.stages[L.stage];
    const w1 = toWorld(L.parent.body, L.a1), w2 = toWorld(L.child.body, L.a2);
    const d = [w2[0] - w1[0], w2[1] - w1[1], w2[2] - w1[2]];
    if (st.type === 'crush') {
      const dl = qRot(qInv(L.parent.body.rotation()), d);
      L.crush = Math.max(0, -dl[0]);
      L.drift = Math.hypot(dl[1], dl[2]);
    } else L.drift = Math.hypot(d[0], d[1], d[2]);
    let fc = 0;
    if (L.subtree) { for (const q of L.subtree) if (q.alive && q.attached) fc += q.fcAvg; }
    else fc = L.child.fcAvg;
    L.fc = fc;
    let weak = 1;
    if (L.weakBy) weak = 1 - 0.65 * Math.max(crushRatio(L.weakBy[0]), crushRatio(L.weakBy[1]));
    const fail = fc > st.sC * weak || L.drift > st.drift || (st.aI && L.child.accAvg > st.aI * weak) ||
      (st.dep && crushRatio(st.dep.link) > st.dep.ratio);
    if (fail) advanceLink(S, L);
  }
}

function advanceLink(S, L) {
  const w = S.world;
  if (L.joint) { w.removeImpulseJoint(L.joint, true); L.joint = null; }
  L.stage++;
  const st = L.stages[L.stage];
  const c = L.child;
  if (!st) {
    L.alive = false;
    c.attached = c.links.some(l => l.alive);
    if (L.shatter) { shatter(S, c); return; }
    S.fxq.push({ k: 'pop', p: toWorld(c.body, L.a2) });
    if (!c.attached && c.name.startsWith('wheel')) c.body.setAngularDamping(0.25);
    return;
  }
  if (st.type === 'hinge') {
    const aC = [st.at[0] - c.c[0], st.at[1] - c.c[1], st.at[2] - c.c[2]];
    const Pw = toWorld(c.body, aC), aP = toLocal(L.parent.body, Pw);
    L.a1 = aP; L.a2 = aC;
    L.joint = w.createImpulseJoint(RAPIER.JointData.revolute(V3(...aP), V3(...aC), V3(...st.axis)), L.parent.body, c.body, true);
    if (L.noContacts) L.joint.setContactsEnabled(false);
    if (st.kick) {
      const kp = toWorld(c.body, [st.kick.at[0] - c.c[0], st.kick.at[1] - c.c[1], st.kick.at[2] - c.c[2]]);
      const dir = qRot(L.parent.body.rotation(), st.kick.dir), m = c.mass * st.kick.dv;
      c.body.applyImpulseAtPoint(V3(dir[0] * m, dir[1] * m, dir[2] * m), V3(...kp), true);
    }
    if (st.nudge) for (const q of [L.parent, c]) q.body.applyImpulseAtPoint(V3(0, q.mass * st.nudge, 0), V3(...Pw), true);
    S.fxq.push({ k: 'creak', p: Pw });
  } else if (st.type === 'crush') {
    const Pw = toWorld(c.body, L.a2), aP = toLocal(L.parent.body, Pw);
    L.a1 = aP;
    const j = w.createImpulseJoint(RAPIER.JointData.prismatic(V3(...aP), V3(...L.a2), V3(1, 0, 0)), L.parent.body, c.body, true);
    j.setLimits(-st.travel, st.travel);
    j.configureMotorModel(RAPIER.MotorModel.ForceBased);
    j.configureMotorVelocity(0, st.damp);
    j.setContactsEnabled(false);
    L.joint = j;
    S.fxq.push({ k: 'crunch', p: Pw });
    if (L.onCrush) for (const D of L.onCrush) if (D.alive && D.stage === 0) advanceLink(S, D);
  }
}

function shatter(S, part) {
  if (!part.alive) return;
  const b = part.body, t = b.translation(), q = b.rotation(), v = b.linvel(), av = b.angvel(), G = part.glass;
  for (const L of part.links) { L.alive = false; L.joint = null; }
  for (const c of part.cols) S.cmap.delete(c.handle);
  S.world.removeRigidBody(b);
  part.alive = false; part.attached = false; part.rec.alive = false;
  part.obj.removeFromParent();
  part.obj.traverse(o => { if (o.isMesh) o.geometry.dispose(); });

  let e1, e2, n, du, dv;
  const cells = [];
  if (G.kind === 'tilt') {
    const cs = Math.cos(G.rz), sn = Math.sin(G.rz);
    e1 = [cs, sn, 0]; n = [-sn, cs, 0]; e2 = [0, 0, 1];
    du = 2 * G.hu / G.nx; dv = 2 * G.hw / G.ny;
    for (let i = 0; i < G.nx; i++) for (let j = 0; j < G.ny; j++) {
      const u = -G.hu + (i + 0.5) * du, s = -G.hw + (j + 0.5) * dv;
      cells.push([e1[0] * u, e1[1] * u, s]);
    }
  } else {
    e1 = [1, 0, 0]; n = [0, 0, 1]; e2 = [0, -1, 0];
    const xs = G.poly.map(p => p[0]), ys = G.poly.map(p => p[1]);
    const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
    du = (x1 - x0) / G.nx; dv = (y1 - y0) / G.ny;
    const inside = (x, y) => {
      let c = false;
      for (let i = 0, j = G.poly.length - 1; i < G.poly.length; j = i++) {
        const [xi, yi] = G.poly[i], [xj, yj] = G.poly[j];
        if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) c = !c;
      }
      return c;
    };
    for (let i = 0; i < G.nx; i++) for (let j = 0; j < G.ny; j++) {
      const x = x0 + (i + 0.5) * du, y = y0 + (j + 0.5) * dv;
      if (inside(x, y)) cells.push([x - part.c[0], y - part.c[1], G.zc - part.c[2]]);
    }
  }
  if (!cells.length) return;
  const qb = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(
    new THREE.Vector3(...e1), new THREE.Vector3(...n), new THREE.Vector3(...e2)));
  const qw = new THREE.Quaternion(q.x, q.y, q.z, q.w).multiply(qb);
  const nW = qRot(q, n), e1W = qRot(q, e1), thick = 0.012, mEach = part.mass / cells.length;
  for (let i = 0; i < cells.length; i++) {
    const seed = S.shardSeed + i * 3, h1 = hash01(seed), h2 = hash01(seed + 1), h3 = hash01(seed + 2);
    const sx = du * (0.8 + 0.16 * h1), sz = dv * (0.8 + 0.16 * h2);
    const rr = qRot(q, cells[i]);
    const px = t.x + rr[0], py = t.y + rr[1], pz = t.z + rr[2];
    const push = (h3 - 0.5) * 2.4, slide = (h1 - 0.5) * 1.2;
    const vx = v.x + av.y * rr[2] - av.z * rr[1] + nW[0] * push + e1W[0] * slide;
    const vy = v.y + av.z * rr[0] - av.x * rr[2] + nW[1] * push + e1W[1] * slide + 0.4;
    const vz = v.z + av.x * rr[1] - av.y * rr[0] + nW[2] * push + e1W[2] * slide;
    const body = S.world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(px, py, pz).setRotation(qw)
      .setLinvel(vx, vy, vz).setAngvel(V3(av.x + (h2 - 0.5) * 9, av.y + (h3 - 0.5) * 9, av.z + (h1 - 0.5) * 9))
      .setCcdEnabled(true).setLinearDamping(0.06).setAngularDamping(0.25));
    const col = S.world.createCollider(RAPIER.ColliderDesc.cuboid(sx / 2, thick / 2 + 0.002, sz / 2)
      .setDensity(mEach / (sx * sz * (thick + 0.004))).setFriction(0.6).setRestitution(0.1).setCollisionGroups(CG_PART), body);
    const mesh = new THREE.Mesh(SHARD_GEOS[(i + S.shardSeed) % SHARD_GEOS.length], MAT.glass);
    mesh.scale.set(sx, thick, sz); mesh.castShadow = true;
    const obj = new THREE.Group(); obj.add(mesh); obj.position.set(px, py, pz); obj.quaternion.copy(qw); S.root.add(obj);
    const rec = track(S, body, obj, { kind: 'shard', foot: [sx / 2, sz / 2], hy: 0.01, op: 0.16 });
    S.cmap.set(col.handle, { shard: rec, body });
  }
  S.shardSeed += 97;
  S.fxq.push({ k: 'glass', p: [t.x, t.y, t.z], v: [v.x, v.y, v.z] });
}

function postStep(S) {
  const car = S.car;
  if (S.phase === 2 && !S.braked && S.t > S.impactT + 0.12) {
    S.braked = true;
    for (const nm of WHEELS) { const w = car.P[nm]; if (w.alive && w.attached) w.body.setAngularDamping(28); }
  }
  S.shake *= Math.exp(-3.2 * DT);
  if (S.phase === 1 && S.t > 40) S.phase = 3;
  if (S.phase === 2 && S.t > S.impactT + 2.5 && S.steps % 30 === 0) {
    let mv = 0;
    for (const p of car.parts) if (p.alive) { const v = p.body.linvel(); mv = Math.max(mv, Math.abs(v.x) + Math.abs(v.y) + Math.abs(v.z)); }
    for (const b of S.bricks) if (!b.body.isSleeping()) { const v = b.body.linvel(); mv = Math.max(mv, Math.abs(v.x) + Math.abs(v.y) + Math.abs(v.z)); }
    for (const r of S.tracked) if (r.alive && r.kind === 'shard' && !r.body.isSleeping()) { const v = r.body.linvel(); mv = Math.max(mv, Math.abs(v.x) + Math.abs(v.y) + Math.abs(v.z)); }
    S.calm = mv < 0.12 ? S.calm + 1 : 0;
    if (S.calm >= 4 || S.t > S.impactT + 30) S.phase = 3;
  }
}

