  syncVisuals(S, clamp(S.acc / DT, 0, 1));
  processFX(S);
  updateSkids(S, simDt);
  FX.dust.update(simDt); FX.spark.update(simDt);
  updateCamera(S, rdt);
  updateShadow(S);
  sky.position.copy(camera.position);
  MAT.startLamp.emissiveIntensity = S.t < S.launchT ? 3 : 0.03;
  const u = renderer.getDrawingBufferSize(_db).y * 0.5 * camera.projectionMatrix.elements[5];
  FX.dust.mat.uniforms.uScale.value = u; FX.spark.mat.uniforms.uScale.value = u;
  renderer.render(scene, camera);
  hudT -= rdt;
  if (hudT <= 0) { hudT = 0.1; updateHud(S); }
}

