el('bClose').addEventListener('click', () => { panel.hidden = true; bSettings.classList.remove('on'); });
el('bApply').addEventListener('click', () => replay(readSettings()));
el('bDefaults').addEventListener('click', () => { writeSettings(DEFAULTS); replay({ ...DEFAULTS }); });
for (const k in inputs) inputs[k].inp.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); replay(readSettings()); } });
document.addEventListener('click', e => { const b = e.target.closest && e.target.closest('button'); if (b) b.blur(); });
addEventListener('keydown', e => {
  const a = document.activeElement, inNum = a && a.tagName === 'INPUT';
  if (e.code === 'Space') { if (inNum) return; e.preventDefault(); togglePause(); return; }
  if (inNum || e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === 'r' || e.key === 'R') replay(readSettings());
  else if (e.key >= '1' && e.key <= '4') setView(['impact', 'follow', 'top', 'orbit'][+e.key - 1]);
});
addEventListener('resize', () => {
  renderer.setSize(innerWidth, innerHeight);
  camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix();
});

/* ---------------------------------------------------------------- main loop */
let lastT = 0, hudT = 0;
function frame(now) {
  requestAnimationFrame(frame);
  const rdt = clamp((now - lastT) / 1000, 0, 0.1);
  lastT = now;
  const S = sim;
  if (!S) return;
  let simDt = 0;
  if (!state.paused && S.phase < 3) {
    S.acc += rdt * state.speed;
    let n = Math.floor(S.acc / DT);
    if (n > MAX_STEPS) { S.acc = MAX_STEPS * DT + (S.acc % DT); n = MAX_STEPS; }
    for (let i = 0; i < n; i++) {
      if (i === n - 1) { if (n === 1) copyPrev(S); else snap(S, 0); }
      stepSim(S); S.acc -= DT; simDt += DT;
      if (S.phase >= 3) { S.acc = 0; break; }
    }
